     1	const std = @import("std");
     2	const zon = @import("build.zig.zon");
     3	
     4	pub fn build(b: *std.Build) void {
     5	    const target = b.standardTargetOptions(.{});
     6	    const optimize = b.standardOptimizeOption(.{});
     7	
     8	    const codecs_str = b.option(
     9	        []const u8,
    10	        "codecs",
    11	        "Compression codecs (default: all). Values: all, c-only, none, zig-only, or comma-separated list of: c-zstd,zstd,c-snappy,snappy,c-gzip,gzip,c-lz4,lz4,c-brotli,brotli",
    12	    ) orelse "all";
    13	
    14	    const codecs = parseCodecs(codecs_str);
    15	
    16	    const build_options = b.addOptions();
    17	    build_options.addOption(bool, "enable_zstd", codecs.zstd);
    18	    build_options.addOption(bool, "enable_zig_zstd", codecs.zig_zstd);
    19	    build_options.addOption(bool, "supports_zstd", codecs.zstd or codecs.zig_zstd);
    20	    build_options.addOption(bool, "enable_snappy", codecs.snappy);
    21	    build_options.addOption(bool, "enable_zig_snappy", codecs.zig_snappy);
    22	    build_options.addOption(bool, "supports_snappy", codecs.snappy or codecs.zig_snappy);
    23	    build_options.addOption(bool, "enable_gzip", codecs.gzip);
    24	    build_options.addOption(bool, "enable_zig_gzip", codecs.zig_gzip);
    25	    build_options.addOption(bool, "supports_gzip", codecs.gzip or codecs.zig_gzip);
    26	    build_options.addOption(bool, "enable_lz4", codecs.lz4);
    27	    build_options.addOption(bool, "enable_zig_lz4", codecs.zig_lz4);
    28	    build_options.addOption(bool, "supports_lz4", codecs.lz4 or codecs.zig_lz4);
    29	    build_options.addOption(bool, "enable_brotli", codecs.brotli);
    30	    build_options.addOption(bool, "enable_zig_brotli", codecs.zig_brotli);
    31	    build_options.addOption(bool, "supports_brotli", codecs.brotli or codecs.zig_brotli);
    32	    build_options.addOption([]const u8, "version", zon.version);
    33	
    34	    const deps = resolveDeps(b, codecs);
    35	
    36	    // Create a module for the library
    37	    const parquet_mod = b.addModule("parquet", .{
    38	        .root_source_file = b.path("src/lib.zig"),
    39	        .target = target,
    40	        .optimize = optimize,
    41	    });
    42	    parquet_mod.addImport("build_options", build_options.createModule());
    43	
    44	    // Library artifact
    45	    const lib = b.addLibrary(.{
    46	        .name = "parquet",
    47	        .root_module = parquet_mod,
    48	    });
    49	
    50	    configureCodecs(lib.root_module, deps, b);
    51	
    52	    b.installArtifact(lib);
    53	
    54	    // C API shared library (opt-in)
    55	    const c_api = b.option(bool, "c_api", "Build shared library with C ABI exports") orelse false;
    56	    if (c_api) {
    57	        const capi_mod = b.addModule("parquet_capi", .{
    58	            .root_source_file = b.path("src/lib.zig"),
    59	            .target = target,
    60	            .optimize = optimize,
    61	        });
    62	        capi_mod.addImport("build_options", build_options.createModule());
    63	
    64	        const capi_lib = b.addLibrary(.{
    65	            .name = "parquet_capi",
    66	            .root_module = capi_mod,
    67	            .linkage = .dynamic,
    68	        });
    69	
    70	        configureCodecs(capi_lib.root_module, deps, b);
    71	
    72	        b.installArtifact(capi_lib);
    73	        capi_lib.root_module.addIncludePath(b.path("src/api/c"));
    74	        b.installFile("src/api/c/libparquet.h", "include/libparquet.h");
    75	    }
    76	
    77	    // WASM/WASI library (opt-in)
    78	    const wasm_wasi = b.option(bool, "wasm_wasi", "Build WASM library for wasm32-wasi") orelse false;
    79	    if (wasm_wasi) {
    80	        const wasi_target = b.resolveTargetQuery(.{
    81	            .cpu_arch = .wasm32,
    82	            .os_tag = .wasi,
    83	        });
    84	
    85	        const wasm_opts = b.addOptions();
    86	        wasm_opts.addOption(bool, "enable_zstd", codecs.zstd);
    87	        wasm_opts.addOption(bool, "enable_zig_zstd", codecs.zig_zstd);
    88	        wasm_opts.addOption(bool, "supports_zstd", codecs.zstd or codecs.zig_zstd);
    89	        wasm_opts.addOption(bool, "enable_snappy", codecs.snappy);
    90	        wasm_opts.addOption(bool, "enable_zig_snappy", codecs.zig_snappy);
    91	        wasm_opts.addOption(bool, "supports_snappy", codecs.snappy or codecs.zig_snappy);
    92	        wasm_opts.addOption(bool, "enable_gzip", codecs.gzip);
    93	        wasm_opts.addOption(bool, "enable_zig_gzip", codecs.zig_gzip);
    94	        wasm_opts.addOption(bool, "supports_gzip", codecs.gzip or codecs.zig_gzip);
    95	        wasm_opts.addOption(bool, "enable_lz4", codecs.lz4);
    96	        wasm_opts.addOption(bool, "enable_zig_lz4", codecs.zig_lz4);
    97	        wasm_opts.addOption(bool, "supports_lz4", codecs.lz4 or codecs.zig_lz4);
    98	        wasm_opts.addOption(bool, "enable_brotli", codecs.brotli);
    99	        wasm_opts.addOption(bool, "enable_zig_brotli", codecs.zig_brotli);
   100	        wasm_opts.addOption(bool, "supports_brotli", codecs.brotli or codecs.zig_brotli);
   101	        wasm_opts.addOption([]const u8, "version", zon.version);
   102	
   103	        const wasi_mod = b.addModule("parquet_wasi", .{
   104	            .root_source_file = b.path("src/lib.zig"),
   105	            .target = wasi_target,
   106	            .optimize = optimize,
   107	        });
   108	        wasi_mod.addImport("build_options", wasm_opts.createModule());
   109	
   110	        const wasi_lib = b.addExecutable(.{
   111	            .name = "parquet_wasi",
   112	            .root_module = wasi_mod,
   113	        });
   114	
   115	        wasi_lib.entry = .disabled;
   116	        wasi_lib.rdynamic = true;
   117	
   118	        configureCodecs(wasi_lib.root_module, deps, b);
   119	
   120	        b.installArtifact(wasi_lib);
   121	    }
   122	
   123	    // WASM freestanding library (opt-in, always no codecs)
   124	    const wasm_freestanding = b.option(bool, "wasm_freestanding", "Build WASM library for wasm32-freestanding (no compression)") orelse false;
   125	    if (wasm_freestanding) {
   126	        const freestanding_target = b.resolveTargetQuery(.{
   127	            .cpu_arch = .wasm32,
   128	            .os_tag = .freestanding,
   129	        });
   130	
