   132	        freestanding_opts.addOption(bool, "enable_zstd", false);
   133	        freestanding_opts.addOption(bool, "enable_zig_zstd", false);
   134	        freestanding_opts.addOption(bool, "supports_zstd", false);
   135	        freestanding_opts.addOption(bool, "enable_snappy", false);
   136	        freestanding_opts.addOption(bool, "enable_zig_snappy", false);
   137	        freestanding_opts.addOption(bool, "supports_snappy", false);
   138	        freestanding_opts.addOption(bool, "enable_gzip", false);
   139	        freestanding_opts.addOption(bool, "enable_zig_gzip", false);
   140	        freestanding_opts.addOption(bool, "supports_gzip", false);
   141	        freestanding_opts.addOption(bool, "enable_lz4", false);
   142	        freestanding_opts.addOption(bool, "enable_zig_lz4", false);
   143	        freestanding_opts.addOption(bool, "supports_lz4", false);
   144	        freestanding_opts.addOption(bool, "enable_brotli", false);
   145	        freestanding_opts.addOption(bool, "enable_zig_brotli", false);
   146	        freestanding_opts.addOption(bool, "supports_brotli", false);
   147	        freestanding_opts.addOption([]const u8, "version", zon.version);
   148	
   149	        const freestanding_mod = b.addModule("parquet_freestanding", .{
   150	            .root_source_file = b.path("src/lib.zig"),
   151	            .target = freestanding_target,
   152	            .optimize = optimize,
   153	        });
   154	        freestanding_mod.addImport("build_options", freestanding_opts.createModule());
   155	
   156	        const freestanding_lib = b.addExecutable(.{
   157	            .name = "parquet_freestanding",
   158	            .root_module = freestanding_mod,
   159	        });
   160	
   161	        freestanding_lib.entry = .disabled;
   162	        freestanding_lib.rdynamic = true;
   163	
   164	        b.installArtifact(freestanding_lib);
   165	    }
   166	
   167	    // Unit tests
   168	    const test_mod = b.addModule("parquet_test", .{
   169	        .root_source_file = b.path("src/lib.zig"),
   170	        .target = target,
   171	        .optimize = optimize,
   172	    });
   173	    test_mod.addImport("build_options", build_options.createModule());
   174	
   175	    const lib_unit_tests = b.addTest(.{
   176	        .root_module = test_mod,
   177	    });
   178	
   179	    configureCodecs(lib_unit_tests.root_module, deps, b);
   180	
   181	    const run_lib_unit_tests = b.addRunArtifact(lib_unit_tests);
   182	
   183	    const check_test_files = b.addSystemCommand(&.{
   184	        "sh", "-c",
   185	        \\test -f ../test-files-arrow/basic/basic_types_plain_uncompressed.parquet || {
   186	        \\  echo ""
   187	        \\  echo "ERROR: Test files not found."
   188	        \\  echo "Generate them first:  cd test-files-arrow && uv run python generate.py"
   189	        \\  echo ""
   190	        \\  exit 1
   191	        \\}
   192	    });
   193	    run_lib_unit_tests.step.dependOn(&check_test_files.step);
   194	
   195	    const test_step = b.step("test", "Run unit tests");
   196	    test_step.dependOn(&run_lib_unit_tests.step);
   197	
   198	    // WASM smoke test: compile both WASM targets (no codecs) to verify exports link
