   200	    {
   201	        const wasi_target = b.resolveTargetQuery(.{ .cpu_arch = .wasm32, .os_tag = .wasi });
   202	        const wasi_opts = b.addOptions();
   203	        wasi_opts.addOption(bool, "enable_zstd", false);
   204	        wasi_opts.addOption(bool, "enable_zig_zstd", false);
   205	        wasi_opts.addOption(bool, "supports_zstd", false);
   206	        wasi_opts.addOption(bool, "enable_snappy", false);
   207	        wasi_opts.addOption(bool, "enable_zig_snappy", false);
   208	        wasi_opts.addOption(bool, "supports_snappy", false);
   209	        wasi_opts.addOption(bool, "enable_gzip", false);
   210	        wasi_opts.addOption(bool, "enable_zig_gzip", false);
   211	        wasi_opts.addOption(bool, "supports_gzip", false);
   212	        wasi_opts.addOption(bool, "enable_lz4", false);
   213	        wasi_opts.addOption(bool, "enable_zig_lz4", false);
   214	        wasi_opts.addOption(bool, "supports_lz4", false);
   215	        wasi_opts.addOption(bool, "enable_brotli", false);
   216	        wasi_opts.addOption(bool, "enable_zig_brotli", false);
   217	        wasi_opts.addOption(bool, "supports_brotli", false);
   218	        wasi_opts.addOption([]const u8, "version", zon.version);
   219	        const wasi_mod = b.addModule("parquet_wasi_smoke", .{
   220	            .root_source_file = b.path("src/lib.zig"),
   221	            .target = wasi_target,
   222	            .optimize = optimize,
   223	        });
   224	        wasi_mod.addImport("build_options", wasi_opts.createModule());
   225	        const wasi_lib = b.addExecutable(.{
   226	            .name = "parquet_wasi_smoke",
   227	            .root_module = wasi_mod,
   228	        });
   229	        wasi_lib.entry = .disabled;
   230	        wasi_lib.rdynamic = true;
   231	        wasm_smoke_step.dependOn(&wasi_lib.step);
   232	    }
   233	    {
   234	        const free_target = b.resolveTargetQuery(.{ .cpu_arch = .wasm32, .os_tag = .freestanding });
   235	        const free_opts = b.addOptions();
   236	        free_opts.addOption(bool, "enable_zstd", false);
   237	        free_opts.addOption(bool, "enable_zig_zstd", false);
   238	        free_opts.addOption(bool, "supports_zstd", false);
   239	        free_opts.addOption(bool, "enable_snappy", false);
   240	        free_opts.addOption(bool, "enable_zig_snappy", false);
   241	        free_opts.addOption(bool, "supports_snappy", false);
