   268	// =========================================================================
   269	// Codec configuration
   270	// =========================================================================
   271	
   272	const Codecs = struct {
   273	    zstd: bool, // C libzstd (opt-in via c-only or explicit codec name)
   274	    zig_zstd: bool, // pure Zig zstd
   275	    snappy: bool, // C++ snappy (opt-in via c-only or explicit codec name)
   276	    zig_snappy: bool, // pure Zig snappy
   277	    gzip: bool, // C zlib (opt-in via c-only or explicit codec name)
   278	    zig_gzip: bool, // pure Zig gzip
   279	    lz4: bool, // C lz4 (opt-in via c-only or explicit codec name)
   280	    zig_lz4: bool, // pure Zig lz4
   281	    brotli: bool, // C brotli (opt-in via c-only or explicit codec name)
   282	    zig_brotli: bool, // pure Zig brotli
   283	
   284	    fn anyC(self: Codecs) bool {
   285	        return self.zstd or self.snappy or self.gzip or self.lz4 or self.brotli;
   286	    }
   287	};
   288	
   289	fn parseCodecs(str: []const u8) Codecs {
   290	    if (std.mem.eql(u8, str, "all")) return .{ .zstd = true, .zig_zstd = true, .snappy = true, .zig_snappy = true, .gzip = true, .zig_gzip = true, .lz4 = true, .zig_lz4 = true, .brotli = true, .zig_brotli = true };
   291	    if (std.mem.eql(u8, str, "c-only")) return .{ .zstd = true, .zig_zstd = false, .snappy = true, .zig_snappy = false, .gzip = true, .zig_gzip = false, .lz4 = true, .zig_lz4 = false, .brotli = true, .zig_brotli = false };
   292	    if (std.mem.eql(u8, str, "none")) return .{ .zstd = false, .zig_zstd = false, .snappy = false, .zig_snappy = false, .gzip = false, .zig_gzip = false, .lz4 = false, .zig_lz4 = false, .brotli = false, .zig_brotli = false };
   293	    if (std.mem.eql(u8, str, "zig-only")) return .{ .zstd = false, .zig_zstd = true, .snappy = false, .zig_snappy = true, .gzip = false, .zig_gzip = true, .lz4 = false, .zig_lz4 = true, .brotli = false, .zig_brotli = true };
   294	    return .{
   295	        .zstd = containsCodec(str, "c-zstd"),
   296	        .zig_zstd = containsCodec(str, "zstd"),
   297	        .snappy = containsCodec(str, "c-snappy"),
   298	        .zig_snappy = containsCodec(str, "snappy"),
   299	        .gzip = containsCodec(str, "c-gzip"),
   300	        .zig_gzip = containsCodec(str, "gzip"),
   301	        .lz4 = containsCodec(str, "c-lz4"),
   302	        .zig_lz4 = containsCodec(str, "lz4"),
   303	        .brotli = containsCodec(str, "c-brotli"),
   304	        .zig_brotli = containsCodec(str, "brotli"),
   305	    };
   306	}
   307	
   308	fn containsCodec(csv: []const u8, name: []const u8) bool {
   309	    var iter = std.mem.splitScalar(u8, csv, ',');
   310	    while (iter.next()) |token| {
   311	        const trimmed = std.mem.trim(u8, token, " ");
   312	        if (std.mem.eql(u8, trimmed, name)) return true;
   313	    }
   314	    return false;
   315	}
   316	
   317	const Deps = struct {
   318	    lz4: ?*std.Build.Dependency,
   319	    brotli: ?*std.Build.Dependency,
   320	    snappy: ?*std.Build.Dependency,
   321	    zstd: ?*std.Build.Dependency,
   322	    zlib: ?*std.Build.Dependency,
   323	    codecs: Codecs,
   324	};
   325	
   326	fn resolveDeps(b: *std.Build, codecs: Codecs) Deps {
   327	    return .{
   328	        .lz4 = if (codecs.lz4) b.dependency("lz4", .{}) else null,
   329	        .brotli = if (codecs.brotli) b.dependency("brotli", .{}) else null,
   330	        .snappy = if (codecs.snappy) b.dependency("snappy", .{}) else null,
   331	        .zstd = if (codecs.zstd) b.dependency("zstd", .{}) else null,
   332	        .zlib = if (codecs.gzip) b.dependency("zlib", .{}) else null,
   333	        .codecs = codecs,
   334	    };
   335	}
   336	
   337	fn configureCodecs(module: *std.Build.Module, deps: Deps, b: *std.Build) void {
   338	    if (!deps.codecs.anyC()) return;
   339	
   340	    if (deps.lz4) |dep| {
   341	        module.addIncludePath(dep.path("lib"));
   342	        module.addCSourceFile(.{
   343	            .file = dep.path("lib/lz4.c"),
   344	            .flags = &.{"-DXXH_NAMESPACE=LZ4_"},
   345	        });
   346	    }
   347	
   348	    if (deps.brotli) |dep| {
   349	        module.addIncludePath(dep.path("c/include"));
   350	        for (brotli_common_sources) |src| {
   351	            module.addCSourceFile(.{ .file = dep.path(src), .flags = &.{} });
   352	        }
   353	        for (brotli_dec_sources) |src| {
