    22	        .optimize = optimize,
    23	    });
    24	
    25	    // Add the parquet module as import
    26	    pq_mod.addImport("parquet", parquet_dep.module("parquet"));
    27	    pq_mod.addImport("build_options", build_options.createModule());
    28	
    29	    const exe = b.addExecutable(.{
    30	        .name = "pqi",
    31	        .root_module = pq_mod,
    32	    });
    33	
    34	    b.installArtifact(exe);
    35	
    36	    // Run step
    37	    const run_cmd = b.addRunArtifact(exe);
    38	    run_cmd.step.dependOn(b.getInstallStep());
    39	
    40	    if (b.args) |args| {
    41	        run_cmd.addArgs(args);
    42	    }
    43	
    44	    const run_step = b.step("run", "Run the pqi CLI");
    45	    run_step.dependOn(&run_cmd.step);
    46	
    47	    // Unit tests for helper functions
    48	    const unit_test_mod = b.addModule("test_helpers", .{
    49	        .root_source_file = b.path("src/test_helpers.zig"),
    50	        .target = target,
    51	        .optimize = optimize,
    52	    });
    53	    const unit_tests = b.addTest(.{
    54	        .root_module = unit_test_mod,
    55	    });
    56	    const run_unit_tests = b.addRunArtifact(unit_tests);
    57	
    58	    // Integration tests (require pq binary to be built first)
    59	    const integration_test_mod = b.addModule("test_integration", .{
    60	        .root_source_file = b.path("src/test_integration.zig"),
    61	        .target = target,
