    64	    const integration_tests = b.addTest(.{
    65	        .root_module = integration_test_mod,
    66	    });
    67	    const run_integration_tests = b.addRunArtifact(integration_tests);
    68	    // Integration tests depend on the executable being built
    69	    run_integration_tests.step.dependOn(b.getInstallStep());
    70	
    71	    // Combined test step
